/*
 * Finder and Process Manager resources of the classic Mac OS (Retro68)
 * Pegged application, compiled by Rez and appended after Retro68's
 * application template, whose SIZE resource the one here replaces.
 *
 * icons.r is generated by make-icons.py from sizes/.
 */

#include "Processes.r"
#include "Finder.r"
#include "MacTypes.r"

#include "icons.r"

/*
 * wxWidgets needs a much bigger partition than Retro68's 1 MB default. On
 * 68k the code segments (about 7 MB with wxWidgets) are loaded into the
 * partition; on PowerPC, with virtual memory off, the whole code fragment
 * (about 13 MB) is. On top of that come the help pages and their window.
 * The sizes are checked after a build; the PowerPC values are also the fat
 * application's. The Finder's Get Info window can change either.
 */
#ifndef WXPEGGED_PREFERRED_SIZE
#  ifdef WXPEGGED_PPC
#    define WXPEGGED_PREFERRED_SIZE (24 * 1024 * 1024)
#    define WXPEGGED_MINIMUM_SIZE   (18 * 1024 * 1024)
#  else
#    define WXPEGGED_PREFERRED_SIZE (14 * 1024 * 1024)
#    define WXPEGGED_MINIMUM_SIZE   (10 * 1024 * 1024)
#  endif
#endif
resource 'SIZE' (-1) {
    reserved,
    acceptSuspendResumeEvents,
    reserved,
    canBackground,
    doesActivateOnFGSwitch,
    backgroundAndForeground,
    dontGetFrontClicks,
    ignoreChildDiedEvents,
    is32BitCompatible,
    isHighLevelEventAware,
    onlyLocalHLEvents,
    notStationeryAware,
    dontUseTextEditServices,
    reserved,
    reserved,
    reserved,
    WXPEGGED_PREFERRED_SIZE,
    WXPEGGED_MINIMUM_SIZE
};

resource 'vers' (1) {
    0x01, 0x00, release, 0x00,
    verUS,
    "1.0",
    "1.0, wxWidgets port of Pegged"
};

resource 'vers' (2) {
    0x01, 0x00, release, 0x00,
    verUS,
    "1.0",
    "Pegged 1.0"
};

/* The owner (signature) resource of the 'WXPG' creator. */
type 'WXPG' as 'STR ';

resource 'WXPG' (0, "Owner resource") {
    "Pegged 1.0"
};

resource 'BNDL' (128) {
    'WXPG', 0,
    {
        'ICN#', { 0, 128 };
        'FREF', { 0, 128 }
    }
};

resource 'FREF' (128) { 'APPL', 0, "" };
